  var G = window.WX_GIBO_ADD = window.WX_GIBO_ADD || { add: [], memo: [], fix: [] };
  G.add = (G.add || []).concat([{"dv": 1, "holder": "n95", "map": "", "zone": "", "memo": "🔒 마지막 장: 1465년 사흘의 검은 비, 그리고 '돌려줄 데'가 생기는 날. 위삼이 갖고 있다.", "pool": "", "status": "보유", "src": "NPC 소지", "id": "g116", "no": 116, "n": "천우록", "han": "千雨錄", "cat": "서책", "e": "비급. 천우산화와 청우검을 익힐 수 있다(무공 수에 포함, 경지 제한 한 단계 낮춤). 세션에 1번, GM에게 앞일 하나를 묻는다(GM은 사실을 하나 답하되 언제인지는 말하지 않아도 된다).", "d": "천 줄기 비의 기록\n원말 협왕이 금릉 옥에서 마지막 장을 썼다\n\n무당의 늙은 도사가 술에 취해 한 세 마디가 첫 장에 있다\n마지막 장에는 백 년 뒤의 검은 비가 적혀 있다\n그는 그 장을 쓰고 웃으며 죽었다고 한다"}, {"dv": 1, "holder": "", "map": "noegong", "zone": "jy", "memo": "암야전 종유굴 깊은 곳 벽에 걸려 있다. 🔒 암야전 전주들은 이것을 '반면교사'로 걸어 두었다.", "pool": "", "status": "배치", "src": "히든피스", "id": "g117", "no": 117, "n": "의살계첩", "han": "義殺戒帖", "cat": "서책", "e": "의살삼계를 익힌 자가 지니면 마기 한계 +1. 계율을 어긴 전투가 끝나면 이 효과를 잃고, 다음 세션까지 돌아오지 않는다.", "d": "두 글자와 세 줄\n무당 개파조사의 친필\n\n칼 없는 자는 베지 않는다\n의뢰는 받지 않는다\n벤 뒤에는 이름을 남긴다\n\n이것을 지킨 자들은 모두 금의위에 쓸렸다"}, {"dv": 1, "holder": "n98", "map": "", "zone": "", "memo": "🔒 하북팽가 사당 뒤. 팽노만 안다.", "pool": "", "status": "보유", "src": "NPC 소지", "id": "g118", "no": 118, "n": "무적 현판", "han": "無敵懸板", "cat": "기보", "e": "비급. 파산뢰권을 익힐 수 있다(무공 수에 포함). 뇌시 여파산에게 내보이면 뇌시는 그 라운드 행동하지 않는다(전투당 1번). 소지자는 《기세》 판정에 유리점 1.", "d": "벼락 맞은 집의 현판\n두 글자 무적\n\n멸문한 집에서 혼자 살아남은 아이가\n다시 세운 집 대문에 걸었다\n그 집 사람들은 막북으로 가서 하나도 돌아오지 않았다"}, {"dv": 1, "holder": "", "map": "suzhou", "zone": "ch", "memo": "태호 바닥 창랑호 선장실. 노항이 찾는다.", "pool": "", "status": "배치", "src": "히든피스", "id": "g119", "no": 119, "n": "창랑타", "han": "滄浪舵", "cat": "기보", "e": "비급. 키 손잡이 안쪽에 아홉 형이 새겨져 있다: 창랑구첩도를 익힐 수 있다(무공 수에 포함). 수로 연결로 이동하는 판정에 유리점 1. 수면 칸에서 이동 −1을 받지 않는다. 장강수로채 NPC에게 내보이면 첫 대면 판정에 유리점 1.", "d": "창랑호의 키\n원말 소금 뱃사공들의 왕이 마지막으로 잡았던 것\n\n평강이 떨어지던 날\n그는 이 키를 잡고 태호로 나갔다\n배는 가라앉았고 키는 남았다"}, {"dv": 1, "holder": "n97", "map": "", "zone": "", "memo": "🔒 마지막 줄: '천주봉 금전, 접힌 그림'.", "pool": "", "status": "보유", "src": "NPC 소지", "id": "g120", "no": 120, "n": "장삼봉 수색 장부", "han": "搜尋帳簿", "cat": "서책", "e": "무당파·도관·도사와 관련된 조사 판정에 유리점 1. 마지막 줄을 읽은 자는 태극도가 어디 있는지 안다.", "d": "이십 년의 장부\n영락의 금의위가 천하의 도관을 뒤진 기록\n\n찾은 것은 누더기 한 벌과 술잔 하나\n마지막 줄에는 장소 하나만 적혀 있다\n그 줄을 쓴 천호는 그 장소에 갔다 오지 않았다"}, {"dv": 1, "holder": "", "map": "r-hoguang", "zone": "tg", "memo": "", "pool": "", "status": "배치", "src": "히든피스", "id": "g121", "no": 121, "n": "교린", "han": "蛟鱗", "cat": "재료", "e": "장인에게 맡겨 방어구로 만들면 착용자는 받는 사격전 대미지 1 감소(라운드에 1번).", "d": "검은 이무기의 비늘\n한수 태극굴에서 났다\n\n어미는 백 년 전 칼 없는 도사에게 죽었고\n새끼는 검은 비를 맞고 깼다\n비늘에 아직 물기가 마르지 않는다"}, {"dv": 1, "holder": "", "map": "beijing", "zone": "gx", "memo": "🔒 조각들을 모으면 칠야의 '일곱째 밤' 날짜가 나온다. 천마신교가 다시 모이는 날이다.", "pool": "", "status": "배치", "src": "히든피스", "id": "g122", "no": 122, "n": "혼천의 조각", "han": "渾天儀片", "cat": "기보", "e": "세션에 1번, 별을 보고 다음 큰 사건이 일어날 구역 하나를 GM에게서 듣는다.", "d": "부서진 별의 기계\n옛 흠천감 관상대의 혼천의 조각\n\n대도가 떨어지던 밤 일곱 무리가 이것을 챙기려다\n벼락과 비를 맞았다\n조각마다 별자리 하나가 새겨져 있다"}, {"dv": 1, "holder": "", "map": "r-henan", "zone": "", "memo": "개방 장서 어딘가. 🔒 칠야가 가져간 판본이 따로 있다. 그 판본의 여백에 사극 넷의 약점이 적혀 있다.", "pool": "", "status": "배치", "src": "히든피스", "id": "g123", "no": 123, "n": "원말고수록", "han": "元末高手錄", "cat": "서책", "e": "원말·칠야·사극과 관련된 조사 판정에 유리점 1.", "d": "원말 강호 열두 사람의 기록\n개방 팔선이 만들었다\n\n사극이라는 말이 이 책에서 처음 났다\n열두째 줄은 팔선의 농담이었는데\n여섯 해 뒤 그대로 되었다"}, {"dv": 1, "holder": "", "map": "nanjing", "zone": "gb", "memo": "과보 나루 소명왕의 배. 🔒 숙명공→혈교 피의 구결, 현생공→남궁 가문 무공, 내생공→낭인 어딘가. 셋을 모으면 절정의 벽을 넘는다(GM 판단).", "pool": "", "status": "배치", "src": "히든피스", "id": "g124", "no": 124, "n": "삼생첩", "han": "三生帖", "cat": "서책", "e": "비급. 삼생신기를 익힐 수 있다(무공 수에 포함, 경지 제한 한 단계 낮춤). 숙명공·현생공·내생공의 행방을 안다.", "d": "세 생의 첩\n눈 없는 법왕이 동료들에게 나눠 준 것의 목록\n\n지난 생은 피 쪽으로\n이번 생은 검 쪽으로\n다음 생은 바람 쪽으로 갔다"}, {"dv": 1, "holder": "", "map": "nanjing", "zone": "gb", "memo": "🔒 칠야를 아는 자(비연각주·흑상 노장로 등) 앞에 내놓으면 그가 한 번 흔들린다(대면 판정 대성공 취급).", "pool": "", "status": "배치", "src": "히든피스", "id": "g125", "no": 125, "n": "소명왕 금관", "han": "小明王金冠", "cat": "기보", "e": "미륵·명교 신도 NPC를 대면하는 판정에 유리점 1.", "d": "잃은 임금의 관\n홍건이 받든 명목 군주의 금관\n\n과보 나루의 겨울밤 배가 뒤집혔다\n관은 물을 먹어 무거워졌고\n무승 백여 명이 그 관을 둘러싸고 함께 가라앉았다"}, {"dv": 1, "holder": "", "map": "beijing", "zone": "dc", "memo": "동창 서고. 🔒 산문을 역적으로 몰 근거. 동창의 마인 색출령에 쓸 수 있다. 산문 PC에게 가장 위험한 종이(원말에서 명까지 3).", "pool": "", "status": "배치", "src": "히든피스", "id": "g126", "no": 126, "n": "문약 원본", "han": "門約", "cat": "서책", "e": "오대문파 NPC를 대면하는 판정에 유리점 1.", "d": "산문과 황제의 약조\n홍무 4년 금릉에서 맺었다\n\n산문은 땅의 구멍을 지키고\n나라는 산문의 문을 넘지 않는다\n원년 천지혈전에 산문이 산을 내려가던 날\n이 종이는 휴지가 되었다"}, {"dv": 1, "holder": "", "map": "beijing", "zone": "dc", "memo": "동창. 🔒 11위 아래에 이름 대신 '황손' 두 글자가 적힌 줄이 있다. 누가 적었는지 동창도 모른다.", "pool": "", "status": "배치", "src": "히든피스", "id": "g127", "no": 127, "n": "강호척살록", "han": "江湖斬殺錄", "cat": "서책", "e": "강호 인물에 대한 조사 판정에 유리점 1. 세션에 1번, NPC 하나의 약점을 GM에게서 듣는다.", "d": "벨 자의 기록\n영락 14년 금의위가 처음 만들었다\n\n해마다 이름 백을 줄 세웠다\n마지막으로 고친 해는 천지혈전 한 해 전\n그해 판의 절반은 지금 죽었거나 미쳤다"}, {"dv": 1, "holder": "n101", "map": "", "zone": "", "memo": "🔒 동창과 번왕부(서안 진왕부)가 서로 가지려 한다. 황실의 정통을 흔들 수 있는 물건.", "pool": "", "status": "보유", "src": "NPC 소지", "id": "g128", "no": 128, "n": "황각사 목어", "han": "皇覺寺木魚", "cat": "기보", "e": "세션에 1번, 두드리면 그 장면의 모든 PC가 마기 1을 덜어 낸다.", "d": "빗자루 든 중의 목어\n봉양 황각사에서 났다\n\n열일곱 살 행자가 맞다가 깨문 자국이 있다\n행자는 황제가 되었고\n이 목어는 황실이 가장 지우고 싶은 물건이 되었다"}, {"dv": 1, "holder": "", "map": "nanjing", "zone": "xl", "memo": "효릉 던전 깊은 곳. 🔒 용은 하늘을 꿰맨 것이 아니라 천열로 빠져나갔다. 천문이 열리는 밤의 열쇠 하나(원말에서 명까지 1-2).", "pool": "", "status": "배치", "src": "히든피스", "id": "g129", "no": 129, "n": "용 비늘", "han": "龍鱗", "cat": "재료", "e": "장인에게 맡겨 방어구로 만들면 착용자는 마기폭주 판정에 유리점 1.", "d": "종산의 금빛 비늘\n홍무 즉위하던 날 용이 올라가며 떨어뜨렸다\n\n황제는 그 자리를 제 무덤으로 정했다\n무덤지기들은 밤마다 비늘이 숨 쉬는 소리를 듣는다"}, {"dv": 1, "holder": "", "map": "r-fujian", "zone": "ns", "memo": "남소림 터 던전 끝(법왕의 자리). 🔒 상권은 원각. 둘을 맞추면 마공의 '끊는 자리'가 보인다. 마도천하를 끝낼 무기도, 마공을 완성할 지도도 된다.", "pool": "", "status": "배치", "src": "히든피스", "id": "g130", "no": 130, "n": "해맥도 하권", "han": "解脈圖", "cat": "서책", "e": "비급. 해맥지를 익힐 수 있다(무공 수에 포함, 경지 제한 한 단계 낮춤). 마공을 익힌 대상을 노린 명중 판정에 유리점 1(라운드에 1번).", "d": "경맥을 푼 그림\n남쪽 절의 지하 감실에서 그렸다\n\n죽은 사교도의 몸을 열어\n마공이 사람을 어디서 비트는지 적었다\n하권에는 그 비튼 자리를 다시 펴는 법이 있다"}, {"dv": 1, "holder": "", "map": "r-fujian", "zone": "ns", "memo": "장부 방. 🔒 소림 PC가 먹은 것이 알려지면 계율원이 문책한다. 혈림이 실재했다는 증거가 된다.", "pool": "", "status": "배치", "src": "히든피스", "id": "g131", "no": 131, "n": "혈환단", "han": "血還丹", "cat": "단약", "e": "먹으면 생명력을 최대치까지 회복한다. 대신 마기 2가 축적된다. 한 알.", "d": "피로 돌리는 단약\n대환단을 흉내 냈다\n\n구할 수 없는 재료 한 가지를\n사람의 피로 바꿨다\n숭산 방장은 이 단약을 안 날 편지를 끊었다"}, {"dv": 1, "holder": "n105", "map": "", "zone": "", "memo": "🔒 가짜다. 건문은 아무것도 써 주지 않았다. 남소림 외원 장부의 글씨와 대조하면 다르다(정란이 알아본다).", "pool": "", "status": "보유", "src": "NPC 소지", "id": "g132", "no": 132, "n": "적심 혈조", "han": "赤心血詔", "cat": "서책", "e": "적심회·건문 시위 후손 NPC를 대면하는 판정에 유리점 1. 진위를 가리면(《감정》 성공) 효과가 사라지고 사홍의 신뢰를 잃는다.", "d": "붉은 마음의 조서\n사라진 황제가 피로 썼다고 한다\n\n찬탈자의 핏줄을 몰아내라\n이 글을 받든 자를 나의 신하로 삼는다\n\n붓은 정난 무렵의 것이 맞다"}, {"dv": 1, "holder": "", "map": "beijing", "zone": "dc", "memo": "동창 서고, 하문이 지킨다. 🔒 남소림으로 가는 약재 목록이 뒷장에 있다. 1447년의 불은 이 장부에서 시작했다.", "pool": "", "status": "배치", "src": "히든피스", "id": "g133", "no": 133, "n": "무적부 잔권", "han": "武籍簿殘卷", "cat": "서책", "e": "세가·표국 출신 NPC에 대한 조사 판정에 유리점 1. 세션에 1번, 늙은 강호인 하나의 젊은 날 비밀을 GM에게서 듣는다.", "d": "무인의 호적\n정통 연간 동창 무적사가 만들었다\n\n무첩을 받은 자의 이름과 출신과 무공\n천순제가 서고를 태울 때\n한 권이 늙은 환관의 품에 들어갔다"}, {"dv": 1, "holder": "n16", "map": "", "zone": "", "memo": "🔒 위충이 갖고 있다. 위충이 빼 준 이름마다 줄이 그어져 있다. 팽호·원진의 이름이 있다.", "pool": "", "status": "보유", "src": "NPC 소지", "id": "g134", "no": 134, "n": "우공 의용첩", "han": "于公義勇帖", "cat": "서책", "e": "북경·북직례의 낭인·개방·팽가 NPC를 대면하는 판정에 유리점 1.", "d": "성벽에 선 자들의 이름\n토목보 뒤 북경을 지킨 상서가 적었다\n\n무첩이 있든 없든 받았다\n그는 탈문 뒤에 죽었고\n이 종이는 역적 명단이 되었다"}, {"dv": 1, "holder": "", "map": "r-fujian", "zone": "ns", "memo": "장부 방. 🔒 글씨의 주인은 건문제다. 정란이 알아본다.", "pool": "", "status": "배치", "src": "히든피스", "id": "g135", "no": 135, "n": "외원 장부", "han": "外院帳", "cat": "서책", "e": "세션에 1번, 혈림이 벤 자의 이름 하나를 GM에게서 듣는다(PC나 NPC 가문일 수 있다). 소림·적심회·혈교 NPC를 대면할 때 꺼내면 판정에 유리점 1.", "d": "남쪽 절이 벤 자의 이름\n한 사람의 글씨로 사십여 년\n\n적는 이는 늙은 승려였고\n그는 자기가 누구인지 한 번도 적지 않았다"}, {"dv": 1, "holder": "", "map": "seoan", "zone": "hm", "memo": "활묘 던전(임씨 여협의 관). 🔒 원본은 북원 화림(바얀). 잔장에 PC 문파의 조문이 있을 수 있다(GM 판단).", "pool": "", "status": "배치", "src": "히든피스", "id": "g136", "no": 136, "n": "천장무경 잔장", "han": "天藏武經殘章", "cat": "서책", "e": "비급. 간문지를 익힐 수 있다(무공 수에 포함). 세션에 1번, GM에게 무공 하나(PC가 이름을 아는 것)의 조문을 듣는다. 그 무공을 쓴 상대에 대한 회피·명중 판정에 이번 전투 동안 유리점 1. 조문을 남에게 알리면 그 무공의 문파 NPC 전원과 관계가 나빠진다.", "d": "하늘이 감춘 책의 몇 장\n무덤 속 여인이 몰래 베꼈다\n\n무공을 가르치는 글이 아니다\n무공이 처음부터 비워 둔 자리를 적었다\n한 장이면 문파 하나가 끝난다"}, {"dv": 1, "holder": "", "map": "seoan", "zone": "hm", "memo": "활묘 쉼터. 임아가 지킨다.", "pool": "", "status": "배치", "src": "히든피스", "id": "g137", "no": 137, "n": "현빙상", "han": "玄氷床", "cat": "기보", "e": "비급. 이 침상에서 하룻밤 야영하면 활묘심법을 익힐 수 있다(무공 수에 포함). 야영하면 내공 회복 +1, 마기 1 감소(세션당 1번). 옮길 수 없다(무게).", "d": "찬 돌침상\n산 사람의 무덤 한가운데\n\n누우면 숨이 하얗게 나온다\n이 위에서 자란 여인들은\n늙어도 얼굴이 젊었다"}, {"dv": 1, "holder": "", "map": "seoan", "zone": "hm", "memo": "활묘 아래 묘실. 🔒 1269년 임월이 조회에게 먹인 열매의 다른 한 알이다.", "pool": "", "status": "배치", "src": "히든피스", "id": "g138", "no": 138, "n": "망정과", "han": "忘情果", "cat": "단약", "e": "먹으면 독과 감정 판정에 걸린 불리점을 모두 지운다. 대신 이번 세션 동안 '정'에 관련된 배경 하나(연인·원수 따위)의 효과를 쓸 수 없다. 한 알.", "d": "정을 잊는 열매\n망정곡 절벽 아래에서만 연다\n\n망정화 가시의 독을 푸는 유일한 것\n먹은 자는 살지만\n누구를 위해 살았는지 잊는다"}, {"dv": 1, "holder": "", "map": "yungjung", "zone": "yc", "memo": "양양 의총. 수성귀를 물리거나 달래면 무덤 하나에서 나온다. 한정의 것.", "pool": "", "status": "배치", "src": "히든피스", "id": "g139", "no": 139, "n": "칸의 금도", "han": "汗金刀", "cat": "병기", "e": "비급. 칼집 안쪽에 열여덟 수가 새겨져 있다: 삭방장을 익힐 수 있다(무공 수에 포함). 《도》 공격 명중 판정에 유리점 1(라운드에 1번). 북원·몽골 NPC를 대면하면 판정에 유리점 1.", "d": "초원의 금빛 칼\n대칸이 수리를 떨어뜨린 아이에게 내렸다\n\n그 아이는 칸에게 '영웅이 아니다'라고 말했다\n칸은 칼을 거두지 않았다\n아이는 칼을 쓰지 않았다"}, {"dv": 1, "holder": "", "map": "seoan", "zone": "hm", "memo": "활묘 보스(신응).", "pool": "", "status": "배치", "src": "히든피스", "id": "g140", "no": 140, "n": "신응의 깃", "han": "神鷹羽", "cat": "기보", "e": "비급. 깃을 쥐고 하룻밤 바람을 받으면 외팔 협객의 검이 보인다: 독비중검을 익힐 수 있다(무공 수에 포함). 지니면 추락·낙하로 받는 피해 없음. 세션에 1번, 높은 곳에서 뛰어내리는 이동을 판정 없이 성공.", "d": "검은 수리의 깃\n외팔 사내를 검총으로 데려간 새의 자손\n\n바람을 받는다\n빈 소매처럼"}, {"dv": 1, "holder": "n111", "map": "", "zone": "", "memo": "천주 노사. 🔒 의천검·도룡도를 벼린 법. 둘을 다시 벼리거나 하나로 합칠 수 있다.", "pool": "", "status": "보유", "src": "NPC 소지", "id": "g141", "no": 141, "n": "회회 도첩", "han": "回回刀牒", "cat": "서책", "e": "부러지거나 망가진 기보·병기를 다시 벼릴 수 있다(노사와 함께, 하루). 현철이 있으면 신병 하나를 새로 벼릴 수 있다(GM 판단).", "d": "서방 야장의 쇠 글\n쇠의 결을 보는 법\n\n검은 쇠는 불로 녹지 않는다\n결을 따라 두드려야 녹는다\n양양의 어느 밤 이 글대로 칼 둘이 났다"}, {"dv": 1, "holder": "n113", "map": "", "zone": "", "memo": "우장 소지. 🔒 결별 사발(이름 서른)과 맞추면 철우의 피가 서요를 거쳐 야율광풍까지 이어진다는 것을 알 수 있다.", "pool": "", "status": "보유", "src": "NPC 소지", "id": "g142", "no": 142, "n": "안문 석각 탁본", "han": "雁門石刻拓本", "cat": "서책", "e": "개방 NPC를 대면하는 판정에 유리점 1, 또는 개방 장로급 NPC 하나의 입을 다물게 한다(세션에 1번). 안문의 그림자에게 읽어 주면 한 라운드 싸움이 멎는다.", "d": "절벽 바위의 손가락 글씨\n나는 요의 무관이다\n아내의 친정에 가던 길이다\n맹약을 믿었다\n\n개방은 이 탁본을 사지 않는다"}, {"dv": 1, "holder": "", "map": "cheonsan", "zone": "hj", "memo": "허주궁 터 던전 끝. 허주의 바둑돌을 물리거나 판을 풀면 얻는다.", "pool": "", "status": "배치", "src": "히든피스", "id": "g143", "no": 143, "n": "공판기국", "han": "空盤棋局", "cat": "기보", "e": "이 판을 푼 PC는 이후 세션마다 1번, 자기 것 하나(무공·기보 효과)를 그 세션 동안 버리고 다른 판정 하나를 자동 성공으로 바꿀 수 있다.", "d": "빈 바둑판\n돌 몇 개가 놓였다\n\n이기려면 먼저\n제 돌 한 무리를 스스로 죽여야 한다\n화산의 노조는 이 판에서 끝없는 검을 얻었고\n그 맞은편은 빈 배를 얻었다"}, {"dv": 1, "holder": "", "map": "cheonsan", "zone": "hj", "memo": "허주궁 터 던전 끝. 🔒 공판노인이 외운다.", "pool": "", "status": "배치", "src": "히든피스", "id": "g144", "no": 144, "n": "만류귀해공 뒤 반쪽", "han": "萬流歸海功下", "cat": "서책", "e": "비급. 허주궁 터 벽의 앞 반쪽과 함께 읽으면 만류귀해공을 익힐 수 있다(무공 수에 포함). 익힌 자가 지니면 받은 내공으로 생명력을 잃지 않는다. 흡성대법·알묘공 같은 흡성 계열 마공을 익힌 자에게 보여 주면 그 마공의 부작용을 없앨 수 있다(GM 판단).", "d": "받은 만큼 비워라\n\n앞 반쪽은 받는 법\n뒤 반쪽은 비우는 법\n원 중엽의 한 교주는 앞 반쪽만 얻었다\n삼 년 만에 무적이 되었고\n몸 안에서 터졌다"}, {"dv": 1, "holder": "n115", "map": "", "zone": "", "memo": "하연 소지. 🔒 사발 밑에 서른 사람의 이름. 하나가 모용연이다.", "pool": "", "status": "보유", "src": "NPC 소지", "id": "g145", "no": 145, "n": "결별 사발", "han": "訣別碗", "cat": "기보", "e": "세션에 1번, NPC 하나와 의(관계)를 끊는다. 그 NPC는 이후 PC를 해치지도 돕지도 않는다. 반대로 끊긴 의 하나를 다시 이으려면 이 사발 서른 개를 모두 깨야 한다(GM 판단).", "d": "낡은 술사발 서른 개\n한 사발에 한 사람\n\n거란인 방주가 옛 벗들과 의를 끊으며 마셨다\n그 뒤로 강호는 의를 끊을 때\n술 한 사발을 바닥에 붓는다"}, {"dv": 1, "holder": "", "map": "cheonsan", "zone": "hj", "memo": "허주궁 터 빈 궁 옥좌 아래.", "pool": "", "status": "배치", "src": "히든피스", "id": "g146", "no": 146, "n": "금오패", "han": "金烏牌", "cat": "기보", "e": "서하·서역 NPC를 대면하는 판정에 유리점 1. 지니면 설원 칸의 이동·추위 판정에 유리점 1.", "d": "금빛 까마귀 패\n서하 황궁이 강호 고수에게 내린 벼슬\n\n송은 강호를 놓아두었고\n서하는 강호를 불렀다\n불려 간 고수들은 천산 얼음 속에 남았다"}, {"dv": 1, "holder": "", "map": "sungsan", "zone": "gk", "memo": "숭산 장경각. 🔒 범허는 이 비의 뜻을 안다.", "pool": "", "status": "배치", "src": "히든피스", "id": "g147", "no": 147, "n": "청소승의 비", "han": "掃經帚", "cat": "기보", "e": "장경각 비질 무공을 익힌 것처럼 쓸 수 있다(전투당 1번). 소림 NPC를 대면하면 판정에 유리점 1. 계율원 NPC는 이 비를 보면 불쾌해한다.", "d": "낡은 대비 한 자루\n장경각에 기대어 서 있다\n\n마흔 해 동안 비질만 한 승려가\n앉은 채 입적하며 놓았다\n아무도 치우지 않았다"}, {"dv": 1, "holder": "n63", "map": "", "zone": "", "memo": "무림맹주 백리궁 소지. 🔒 휴전의 신호. 퉁소 반쪽은 교주궁 서고. 백리궁이 신교에 반쪽 사본을 보냈다(명대 이전·이후 5).", "pool": "", "status": "보유", "src": "NPC 소지", "id": "g148", "no": 148, "n": "청탁곡 악보", "han": "淸濁曲譜", "cat": "서책", "e": "비급. 청탁곡을 익힐 수 있다(무공 수에 포함). 거문고 반쪽만이라 익힌 자의 청탁곡은 첫 라운드 불리점 대신 GM 판단. 퉁소 반쪽과 합치면 정·사·신교 NPC 하나와 한 장면 동안 칼을 내리게 할 수 있다.", "d": "거문고 반쪽의 악보\n금분세수 자리에서 피를 맞았다\n\n삼십육동의 늙은이들이 깃대 속에 숨겨 왔다\n나머지 반쪽은 천산에 있다"}, {"dv": 1, "holder": "", "map": "beijing", "zone": "dc", "memo": "동창 서고. 🔒 하문이 지킨다. 조 공공의 무공. 벽사검보 뒷면('끊은 것을 다시 이어라')과 맞추면 궁화보의 광증을 풀 수 있다(GM 판단).", "pool": "", "status": "배치", "src": "히든피스", "id": "g149", "no": 149, "n": "궁화보 사본", "han": "宮花譜", "cat": "서책", "e": "익히면 궁화보 무공을 얻는다(경지 제한 무시, 배경 하나를 영구히 잃는다). 읽기만 해도 동창 고수의 수를 안다: 동창 NPC를 상대로 한 회피 판정에 유리점 1(전투당 1번).", "d": "궁중 꽃의 보\n동창 서고 깊은 곳\n\n첫 장에 '먼저 스스로를 끊어라'\n뒷장은 비어 있다\n남쪽 절의 검보에는 뒷장이 있었다"}, {"dv": 1, "holder": "", "map": "hwasan", "zone": "sg", "memo": "화산 사과애. 🔒 청림자가 1441년 협객도로 떠나며 새겼다. 연하의 '다시 핀다'와 합치면 화산의 두 손이 하나가 된다.", "pool": "", "status": "배치", "src": "히든피스", "id": "g150", "no": 150, "n": "사과애 검흔", "han": "思過崖劍痕", "cat": "기보", "e": "동굴에서 하루를 보내면 무초검을 익힐 수 있다(경지 제한 한 단계 낮춤). 화산 PC가 율하낭랑이나 연하에게 이 검흔의 뜻을 전하면 화산 NPC와의 관계 판정에 유리점 1(세션당 1번).", "d": "동굴 벽의 검 자국\n초식이 하나도 없다\n\n떠나는 검객이 새기고\n남는 문파가 막았다\n화산의 두 손 가운데 하나가 여기 있다"}, {"dv": 1, "holder": "", "map": "suzhou", "zone": "cl", "memo": "창랑촌. 손노파가 우물가 사당에 걸어 두었다. 정중히 청하면 베끼게 해 준다.", "pool": "", "status": "배치", "src": "히든피스", "id": "g151", "no": 151, "n": "조승의 권보", "han": "趙昇拳譜", "cat": "서책", "e": "비급. 대조권을 익힐 수 있다(무공 수에 포함). 창랑촌 사람들에게 내보이면 첫 대면 판정에 유리점 1.", "d": "동네 주먹의 기록\n밀물처럼 물러섰다가 덮친다\n\n내 손에선 동네 주먹이던 것이\n그 손에선 강남의 주먹이 되었다\n그거면 됐다"}, {"dv": 1, "holder": "", "map": "r-fujian", "zone": "ns", "memo": "남소림 터 던전 끝(법왕의 자리). 법왕의 잿불을 물리거나 달래면 재 속에서 나온다.", "pool": "", "status": "배치", "src": "히든피스", "id": "g152", "no": 152, "n": "법왕의 염주", "han": "法王念珠", "cat": "기보", "e": "비급. 미륵하생장을 익힐 수 있다(무공 수에 포함). 지니면 괴력난신을 노린 명중 판정에 유리점 1(전투당 1번).", "d": "웃는 불상의 염주\n백여덟 알 가운데 하나가 빠졌다\n\n잃은 임금을 끝내 놓지 못한 법왕이\n마지막까지 돌렸다"}, {"dv": 1, "holder": "n96", "map": "", "zone": "", "memo": "노항 집안 궤짝. 🔒 남은 판. 위삼(천우록 뒷장, 창랑구첩도)과 만나 겨루면 두 비급이 완성된다.", "pool": "", "status": "보유", "src": "NPC 소지", "id": "g153", "no": 153, "n": "협왕신기 한 장", "han": "俠王神氣", "cat": "서책", "e": "비급. 협왕신기를 익힐 수 있다(무공 수에 포함). 창랑구첩도를 익힌 자와 함께 있으면 둘 다 이번 전투 첫 명중 판정에 유리점 1(남은 판).", "d": "협왕이 창랑왕에게 준 한 장\n'남은 판은 아이들이 하겠지'\n\n종이 한 장이지만\n앞을 보는 사람의 숨이 적혀 있다"}, {"dv": 1, "holder": "n102", "map": "", "zone": "", "memo": "연산노기 소지. 늙은 기병이 마지막 제자를 찾는다.", "pool": "", "status": "보유", "src": "NPC 소지", "id": "g154", "no": 154, "n": "연산기 창보", "han": "燕山騎槍譜", "cat": "서책", "e": "비급. 연산창을 익힐 수 있다(무공 수에 포함). 말을 탄 상태라면 연산창의 이동 칸 +1.", "d": "연산 열여덟 기의 창\n곧게 달려 찌른다\n\n황제를 찾으러 남쪽까지 간 셋은\n돌아오지 않았다\n남은 열다섯이 이 창보를 썼다"}, {"dv": 1, "holder": "", "map": "r-fujian", "zone": "ns", "memo": "남소림 터 피의 숲(탑림) 뒤 벽. 🔒 무명이 지킨다. 계율원 사람에게는 보여 주지 않는다.", "pool": "", "status": "배치", "src": "히든피스", "id": "g155", "no": 155, "n": "역계 석벽", "han": "逆戒石壁", "cat": "기보", "e": "비급. 단지장·역계수 가운데 하나를 익힐 수 있다(무공 수에 포함). 둘 다 익히려면 생명력 최대치 −1을 영구히 받아들여야 한다.", "d": "불탄 절 벽의 네 줄\n법명을 끊고 손가락을 끊고\n말을 끊고 돌아갈 곳을 끊는다\n\n벽 아래 손가락뼈가 쌓여 있다"}, {"dv": 1, "holder": "", "map": "sungsan", "zone": "yj", "memo": "원진암. 🔒 원진은 이 구결을 원각에게 넘긴 것을 뉘우친다. 범허 쪽 사람에게만 가르친다.", "pool": "", "status": "배치", "src": "히든피스", "id": "g156", "no": 156, "n": "세마 구결", "han": "洗魔口訣", "cat": "서책", "e": "비급. 세마결을 익힐 수 있다(무공 수에 포함). 원진에게서 직접 배우면 경지 제한 한 단계 낮춤.", "d": "마를 씻는 구결\n파문된 늙은 중이 밭머리에서 외운다\n\n씻은 물이 어디로 흘렀는지\n그는 이제야 묻는다"}, {"dv": 1, "holder": "n105", "map": "", "zone": "", "memo": "사홍 소지. 적갑사가 되겠다고 맹세하면 받는다.", "pool": "", "status": "보유", "src": "NPC 소지", "id": "g157", "no": 157, "n": "적갑 검첩", "han": "赤甲劍帖", "cat": "서책", "e": "비급. 적심검을 익힐 수 있다(무공 수에 포함). 적심회 NPC에게 내보이면 동지로 대접받는다(진짜 동지가 아니어도).", "d": "붉은 속옷 안쪽에 꿰맨 검첩\n검은 겉옷을 벗는 순간부터\n\n사라진 황제의 이름을 건다\n그 황제는 이 검을 본 적이 없다"}, {"dv": 1, "holder": "", "map": "seoan", "zone": "jn", "memo": "종남산 기슭 은거지. 🔒 활묘의 임아가 나머지 반쪽 읽는 법을 안다. 패검종이 이 검보를 노린다.", "pool": "", "status": "배치", "src": "히든피스", "id": "g158", "no": 158, "n": "군숙 쌍검보", "han": "君淑雙劍譜", "cat": "서책", "e": "비급. 두 사람이 함께 읽어야 한다. 군숙합벽을 둘 다 익힐 수 있다(각자 무공 수에 포함).", "d": "두 검을 한 쌍으로\n한 권을 반씩 나눠 적었다\n\n하나는 산 사람의 무덤에서\n하나는 도사의 궁에서"}, {"dv": 1, "holder": "n69", "map": "", "zone": "", "memo": "혈곡 제단. 백영 소지. 🔒 사발 바닥의 피 자국은 마르지 않는다. 혈수 대장로는 혈회에서 이 사발을 백영 손에서 빼앗으려 한다.", "pool": "", "status": "보유", "src": "NPC 소지", "id": "g159", "no": 159, "n": "맹혈완", "han": "盟血碗", "cat": "기보", "e": "지닌 자는 혈교 NPC에게 '주인'으로 대접받는다(혈교 NPC를 대면하는 판정에 유리점 2). 혈회에서 이 사발을 든 자가 주인이다. 혈교 교도가 아닌 자가 지니면 하루에 1번 생명력 1을 잃는다.", "d": "1360년의 사발\n서수휘의 시신에서 받은 피를\n여덟이 나눠 마셨다\n\n주인은 죽어도\n사발은 남았다"}, {"dv": 1, "holder": "", "map": "cheonsan", "zone": "gs", "memo": "골서고 피를 받는 홈. 쇄기·혈사 시신에서 나온다. 🔒 피는 붉은 비 항아리에서 떠낸 것. 갈라 보면 백영이 아니라 마성 쪽으로 기운다. 혈수 대장로에게 가져가면 그의 첫 증거가 된다.", "pool": "", "status": "배치", "src": "히든피스", "id": "g160", "no": 160, "n": "심주", "han": "心珠", "cat": "기보", "e": "혈사·쇄기의 심장 곁에서 꺼낸 붉은 구슬. 지니면 혈교 무공을 노린 회피 판정에 유리점 1(전투당 1번). 《의술》로 가르면 그 피가 어디로 기우는지 본다(GM 진상).", "d": "심장 곁의 붉은 구슬\n주인이 부르면 끓는다\n\n혈사들은 영예로 안다\n주인의 피가 내 심장 곁에 있다"}, {"dv": 1, "holder": "", "map": "cheonsan", "zone": "gs", "memo": "골서고 끝(고기의 자리). 3좌 고기를 물리치면 얻는다. 🔒 맨 끝 장에 '피를 하늘로 보내는 법'의 반쪽. 백영이 찾는 것.", "pool": "", "status": "배치", "src": "히든피스", "id": "g161", "no": 161, "n": "봉혈보", "han": "縫血譜", "cat": "서책", "e": "비급. 봉혈보를 익힐 수 있다(무공 수에 포함). 익힐 때 《상단전》 판정에 실패하면 마기 1을 얻는다. 열일곱 문파 무공 이름을 알 수 있다.", "d": "뼈 위에 적은 보\n열일곱 문파의 수를 피로 꿰맸다\n\n남의 칼을 제 손에 붙이면\n손이 남의 것이 된다"}, {"dv": 1, "holder": "n119", "map": "", "zone": "", "memo": "갈소 소지. 🔒 무림맹 안에 혈맥 셋. 하나는 열일곱 문파 가운데 살아남은 집에 있다.", "pool": "", "status": "보유", "src": "NPC 소지", "id": "g162", "no": 162, "n": "혈맥 장부", "han": "血脈帳簿", "cat": "서책", "e": "세션에 1번, 무림맹이나 중원 문파 NPC 하나가 혈맥(혈교 점조직)인지 GM에게 묻는다. 홍낭방 NPC에게 내보이면 혈교 사람으로 대접받는다.", "d": "약방 장부처럼 꾸몄다\n약재 이름 아래 사람 이름\n\n다섯이 한 맥\n맥의 우두머리는 위 한 사람만 안다"}, {"dv": 1, "holder": "n28", "map": "", "zone": "", "memo": "흑목사자 소지(수석 패). 🔒 열세 번째 패는 천마가 등선하던 밤 사라졌다. 그 패를 가진 자는 교주의 말을 할 수 있다. 흑목사자가 찾는다.", "pool": "", "status": "보유", "src": "NPC 소지", "id": "g163", "no": 163, "n": "흑목령", "han": "黑木令", "cat": "기보", "e": "천마신교 NPC에게 내밀면 교주의 명으로 듣는다(경지가 낮은 교도 NPC는 거역하지 못한다. 세션에 1번). 사람 이름과 함께 쓰면 추살령: 신교 전체가 그 사람을 쫓는다(GM 판단).", "d": "손바닥만 한 검은 나무 패\n성화대의 불이 새겨져 있다\n\n벼락 맞은 소나무로 열셋을 깎았다\n지금 남은 것은 열둘"}, {"dv": 1, "holder": "n126", "map": "", "zone": "", "memo": "사막의 사자 소지. 🔒 중원에 남은 셋의 자리: 하나는 교주궁 성화대 아래(등명노인), 하나는 잔화(천주 초암), 하나는 행방 불명(GM이 정한다).", "pool": "", "status": "보유", "src": "NPC 소지", "id": "g164", "no": 164, "n": "성화패", "han": "聖火牌", "cat": "기보", "e": "익히지 않아도 성화령의 수 하나를 쓸 수 있다(세션에 1번, 판정 하나에 유리점 2). 셋을 모으면 서쪽 본교와 거래할 수 있다(GM 판단).", "d": "쇠패 여섯 가운데 하나\n서쪽 본사가 중원 교주에게 주었다\n\n원나라에 엎드리라는 명을 거역한 뒤\n셋만 중원에 남았다"}, {"dv": 1, "holder": "n124", "map": "", "zone": "", "memo": "여단의 봇짐. 🔒 가장 아래 책에 '범의 탈'(g167).", "pool": "", "status": "보유", "src": "NPC 소지", "id": "g165", "no": 165, "n": "봉요서", "han": "封妖書", "cat": "서책", "e": "세션에 1번 책장을 넘기면 갇힌 요괴가 나와 한 가지 일을 하고 돌아간다(전투에서는 졸개 하나로 한 라운드 싸운다). 넘길 때 《부적》 판정에 실패하면 요괴가 돌아가지 않는다.", "d": "얇은 책 몇 권\n책장마다 무언가 갇혀 있다\n\n무엇이 들었는지는\n서고지기만 안다"}, {"dv": 1, "holder": "", "map": "r-fujian", "zone": "qz", "memo": "천주 교외 초암. 잔화의 마지막 모임터. 🔒 바위 뒤에 중원에 남은 성화패 하나가 묻혀 있다.", "pool": "", "status": "배치", "src": "히든피스", "id": "g166", "no": 166, "n": "초암 석각", "han": "草庵石刻", "cat": "기보", "e": "비급. 삼금령을 익힐 수 있다(무공 수에 포함). 베껴 가면 천마신교 NPC 가운데 옛 명교도(멸원천·잔화)를 대면하는 판정에 유리점 1.", "d": "천주 바닷가 바위\n빛의 부처를 새긴 곁에\n세 줄이 있다\n\n벼슬하지 않는다\n백성을 먼저 먹인다\n교도끼리 치지 않는다"}, {"dv": 1, "holder": "n124", "map": "", "zone": "", "memo": "여단의 봇짐 가장 아래 책. 🔒 백액대왕이 제위철로 돌아온 날 여단이 숨겼다. 이것을 쓰고 장주 방에 들어가면 장주가 고기를 먹지 않는 까닭을 볼 수 있다.", "pool": "", "status": "보유", "src": "NPC 소지", "id": "g167", "no": 167, "n": "범의 탈", "han": "虎面", "cat": "기보", "e": "쓰면 범의 왕탈이 깃든다: 요면 무공을 익힌 것처럼 쓸 수 있고 범으로만 요화한다. 쓴 동안 백액대왕(제위철)의 눈에 보이지 않는다.", "d": "귀주 세 영물 가운데\n범의 얼굴을 본뜬 탈\n\n왕탈 셋 가운데\n하나가 없어졌다"}, {"dv": 1, "holder": "", "map": "seoan", "zone": "pg", "memo": "곡강대 입회인 자리 아래. 서안표국 국주도 날짜 빈 검첩을 하나 가지고 있다. 🔒 국주의 검첩에 날을 적으면 서안이 검규 안으로 들어온다.", "pool": "", "status": "배치", "src": "히든피스", "id": "g168", "no": 168, "n": "검첩", "han": "劍帖", "cat": "기보", "e": "날짜를 비운 패검종 검첩. 날을 적어 패검종 NPC 하나에게 보내면, 그 NPC는 검규에 따라 일대일 비무에 응해야 한다(합공·매복 없음). 이기면 정한 것 하나를 내놓는다(땅·사람·물건·말 하나).", "d": "붉은 끈으로 묶은 검은 대나무 쪽\n날짜가 비어 있다\n\n받은 쪽이 날을 적는다\n지는 쪽이 사는 길이라서\n섬서 사람들은 대개 적는다"}, {"dv": 1, "holder": "n127", "map": "", "zone": "", "memo": "원로원주 모소 소지. 🔒 모용단죽이 목을 묻으러 내려가지 않았다. 앞 종주들의 수를 볼 필요가 없었다.", "pool": "", "status": "보유", "src": "NPC 소지", "id": "g169", "no": 169, "n": "구랑의 목", "han": "九郞首", "cat": "기보", "e": "곡강 검총 다섯째 감실에 묻으면 목 없는 종주들이 싸우지 않고 마지막 수를 보여 준다(단수검보를 얻는다). 지니고 있으면 패검종 원로원 NPC를 대면하는 판정에 유리점 1.", "d": "옻칠한 함 속의 목\n\n다섯째 종주는\n아직 묻히지 않았다"}, {"dv": 1, "holder": "", "map": "seoan", "zone": "gc", "memo": "곡강 검총 끝. 목 없는 종주들을 물리치거나, 구랑의 목을 묻으면 얻는다.", "pool": "", "status": "배치", "src": "히든피스", "id": "g170", "no": 170, "n": "단수검보", "han": "斷首劍譜", "cat": "서책", "e": "비급. 단수검을 익힐 수 있다(무공 수에 포함). 지니면 패검종 종주(모용단죽)를 노린 명중 판정에 유리점 1(전투당 1번).", "d": "목 없는 다섯 종주의 마지막 수\n\n넷을 합치면 반이고\n다섯을 합치면\n지금 종주를 꺾는 한 수"}, {"dv": 1, "holder": "n131", "map": "", "zone": "", "memo": "원랑 소지. 구강의 밤에 원구가 물에 던졌고 원랑이 건졌다.", "pool": "", "status": "보유", "src": "NPC 소지", "id": "g171", "no": 171, "n": "열여덟 채의 깃발", "han": "十八寨旗", "cat": "기보", "e": "옛 장강 열여덟 채의 회맹 깃발. 펼치면 수로채 NPC 가운데 옛 채 출신(동쪽 채들, 십팔망진의 일곱)을 대면하는 판정에 유리점 2. 십팔망진의 열여덟째 자리에 들어설 수 있다.", "d": "물 아래 원구\n물 위 관부\n\n열여덟 채가 한 사람씩 내어\n한 폭에 이름을 꿰맸다"}, {"dv": 1, "holder": "", "map": "sanxia", "zone": "bd", "memo": "백제성 나루 서방 창고. 맹노의 사람에게서 사거나 빼앗는다.", "pool": "", "status": "배치", "src": "히든피스", "id": "g172", "no": 172, "n": "수로채 통행패", "han": "水路寨通行牌", "cat": "기보", "e": "장강의 나루를 값 없이 지나간다(세션 동안). 수로채 배를 한 번 불러 탈 수 있다. 팽가·동창 NPC 앞에서 내보이면 그 장면 동안 적대한다.", "d": "물고기 비늘 모양의 구리 패\n뒷면에 아홉 척의 이름\n\n눈먼 쥐가 매긴 값을\n이미 치렀다는 표"}, {"dv": 1, "holder": "", "map": "r-jiangxi", "zone": "pc", "memo": "파양호 쇠사슬 무덤 끝. 쇠사슬 누선을 물리치면 얻는다.", "pool": "", "status": "배치", "src": "히든피스", "id": "g173", "no": 173, "n": "화선 기록", "han": "火船錄", "cat": "서책", "e": "비급. 화선계를 익힐 수 있다(무공 수에 포함). 수로채 화룡선(불쥐)의 화공을 알아본다: 화공을 노린 회피 판정에 유리점 1.", "d": "1363년 파양호의 불\n바람을 읽고 불배를 띄운 법\n\n수로채 불쥐들이 가진 것은\n이 반쪽이다"}, {"dv": 1, "holder": "n24", "map": "", "zone": "", "memo": "산군 소지. 🔒 맹약 원문에 지워진 한 줄: '길값을 낸 자의 마을은 털지 않는다.' 제강천의 마을 지켜 주기가 여기서 나왔다는 것을 산군만 안다.", "pool": "", "status": "보유", "src": "NPC 소지", "id": "g174", "no": 174, "n": "흑풍 장부", "han": "黑風帳", "cat": "서책", "e": "흑풍채 길꾼들의 길값 장부. 지니면 녹림 NPC와 표국 NPC를 대면하는 판정에 유리점 1. 장부를 보고 《학식》 판정에 성공하면 섬서·산동·하남의 산길 가운데 길꾼이 지키는 길을 안다(그 길로 가면 지치는 판정을 하지 않는다).", "d": "백 년 가까이 적은 길값\n\n맨 앞장에\n산길은 같이 쓰고\n마을은 따로 턴다"}, {"dv": 1, "holder": "", "map": "dongpyeong", "zone": "sa", "memo": "양산 옛 충의당 터. 의자 다리 밑을 파면 나온다. 산군의 길꾼들이 그 터를 지키지만 책이 있는 줄은 모른다.", "pool": "", "status": "배치", "src": "히든피스", "id": "g175", "no": 175, "n": "현녀천서", "han": "玄女天書", "cat": "서책", "e": "비급. 현녀진을 익힐 수 있다(무공 수에 포함). 펼치면 녹림 NPC는 이것을 '두령의 책'으로 알아본다(녹림 NPC를 대면하는 판정에 유리점 2, 세션에 1번).", "d": "구천현녀가 내렸다는 세 권 가운데 하나\n\n양산의 옛 충의당 터\n백팔 의자 가운데 하나의 다리 밑"}, {"dv": 1, "holder": "", "map": "r-shaanxi", "zone": "by", "memo": "백운채 군막. 갈패를 물리치면 얻는다.", "pool": "", "status": "배치", "src": "히든피스", "id": "g176", "no": 176, "n": "백운채 군령패", "han": "白雲寨軍令牌", "cat": "기보", "e": "제강천이 군문 시절 갈패에게 준 쇠 영패. 천강대·군문 출신 NPC에게 내보이면 그 장면 동안 명령 하나를 듣는다(경지가 낮은 자). 제강천에게 가져가면 천강대 서른여섯째 자리와 총채주의 신임을 받는다.", "d": "요동 군문의 쇠 영패\n'천강 서른여섯'\n\n구름 속에서\n아직 군령을 기다린다"}]);
  G.memo = (G.memo || []).concat([{"n": "송문고검", "key": "원영신", "add": "🔒 장삼봉의 원영신 조각이 깃들어 있다. 무당산 위에 있을 때만 온전히 나타난다. 지금 소지자 청허진인 곁의 '누더기 노인'이 그것이다(장삼봉과 원말 사극 1-8)."}, {"n": "태극도", "key": "둘째 원", "add": "🔒 도맥 담연자가 이 그림 위에 장삼봉의 둘째 원을 옮겨 그렸다. 펼치려던 제자 일곱이 상단전이 터졌다. 송문고검의 원영신에게 '네 원에는 색이 있구나'를 들은 자만 안전하게 읽는다(장삼봉과 원말 사극 1-4)."}, {"n": "벽사검보", "key": "역계", "add": "🔒 첫 장 '먼저 스스로를 끊어라'는 남소림 외원(혈림)의 계율 역계의 첫 줄이다(명대 — 혈림 1-2)."}, {"n": "의천검", "key": "한정", "add": "🔒 1273년 양양 함락 전 한정·매소 부부가 현철 검과 서방 강철로 벼렸다. 안에 한정의 무학 전부(매소가 받아 적음). 도룡도와 부딪쳐야 열린다. 한정의 딸 정수(아미 개파조)가 받았다(송말원초 6-3)."}, {"n": "도룡도", "key": "한정", "add": "🔒 1273년 양양에서 한정·매소 부부가 벼렸다. 안에 악비의 편지 한 장(무목유서의 진상). 의천검과 부딪쳐야 열린다. 아들 한파가 메고 죽은 뒤 행방을 잃었다(송말원초 6-3)."}]);
